</input>
</sample_inputs>

Here is the source code:
<source_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String args[]) {
        FastReader input = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        int T = 1;
        while (T-- > 0) {
            String s = input.next();
            out.println(solve(s));
        }
        out.close();
    }

    public static long solve(String s) {
        int n = s.length();

        // Check for leading zero issues
        if (s.charAt(0) == '0') return 0;

        // Collect positions of X characters
        List<Integer> xPositions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'X') {
                xPositions.add(i);
            }
        }

        long total = 0;

        // Try all possible digits for X (0-9)
        for (int digit = 0; digit <= 9; digit++) {
            char[] arr = s.toCharArray();

            // Replace all X with current digit
            for (int pos : xPositions) {
                arr[pos] = (char) (digit + '0');
            }

            // Check if the resulting number has leading zero
            if (arr[0] == '0') continue;

            // Count possibilities for underscores
            long count = 1;
            for (int i = 0; i < n; i++) {
                if (arr[i] == '_') {
                    if (i == 0) {
                        count *= 9; // Cannot be 0 for first position
                    } else {
                        count *= 10;
                    }
                }
            }

            // Check last two digits for divisibility by 25
            int lastTwo = getLastTwoDigits(arr);
            if (lastTwo % 25 == 0) {
                total += count;
            }
        }

        return total;
    }

    public static int getLastTwoDigits(char[] arr) {
        int n = arr.length;
        int tens = -1, ones = -1;

        if (n >= 2) {
            if (arr[n-2] == '_') {
                // We need to consider all possible digits for the tens place
                // But since we're counting possibilities, we'll handle this differently
                // For now, return -1 to indicate we need special handling
                return -1;
            } else {
                tens = arr[n-2] - '0';
            }

            if (arr[n-1] == '_') {
                return -1;
            } else {
                ones = arr[n-1] - '0';
            }
        } else if (n == 1) {
            if (arr[0] == '_') {
                return -1;
            } else {
                return arr[0] - '0';
            }
        }

        if (tens == -1 || ones == -1) return -1;
        return tens * 10 + ones;
    }
}
